-- Generated by tools/prepare_story.py from docs/story.md; edit the reviewed script.
return {
    {key="before-01", phase="before", level=1, lines={
        {"noelle", "Snow on the rooftops, lights in the trees... our Christmas market starts with one little wish.", story.THOUGHT},
        {"agnes", "You're Rosa's girl. You've still got her chin. One stall, no stock, twenty days till Christmas Eve. Well done."},
        {"noelle", "I'm only here for three weeks. I've a train on the twenty-sixth, and a job in the city."},
        {"agnes", "Course you have. Come in when you can't feel your nose. There's buns."},
        {"noelle", "Gran gave me this for someone here, too. \"For whoever needs it most.\" Very helpful, Gran."},
        {"wren", "Good morning, Noelle. Mind the third step. It's a sly one."},
        {"noelle", "Thank you. Sorry, how do you know my...? Oh! Ow. Third step."},
    }},
    {key="after-01", phase="after", level=1, lines={
        {"theo", "Excuse me. Your arch is in my way."},
        {"noelle", "It's a lovely arch. It's the first thing people will see."},
        {"theo", "It's the first thing my trees will hit. I've sold trees from this corner for eleven years."},
        {"noelle", "Then you'll know how to get round it. Merry Christmas!"},
    }},
    {key="after-02", phase="after", level=2, lines={
        {"noelle", "I need timber. A lot of it. I'm told you're the man. Please don't enjoy this."},
        {"theo", "Oh, I'm going to enjoy this. Is that arch made of my offcuts?"},
        {"noelle", "Nothing! It's scrap! Don't touch that, your gloves are sticky!"},
        {"theo", "It's resin. It's a tree thing. You wouldn't understand. You've got one arch."},
    }},
    {key="after-03", phase="after", level=3, lines={
        {"pip", "Message for Mrs Holt! From Mr Strand! He says your chimney's smoking on his side!", story.SHOUT},
        {"agnes", "Tell that man it's a free sky. And tell him he's got his gutters on wrong."},
        {"noelle", "They're thirty feet apart. Why don't they just talk?"},
        {"pip", "They've not talked in forty years. I get a penny a message. It's a good business."},
    }},
    {key="after-04", phase="after", level=4, lines={
        {"theo", "There's your timber. I knocked a bit off. Don't tell anyone."},
        {"noelle", "That's almost kind."},
        {"theo", "It's almost dry, too. Who's that old man sweeping my lot?"},
        {"noelle", "I thought he was yours."},
        {"wren", "Lovely morning, Theo. That one's the good saw, by the way. Behind the stack."},
    }},
    {key="after-05", phase="after", level=5, lines={
        {"pip", "Look what I found behind the old post box! The Kind Word box! You write something nice, no name."},
        {"pip", "Then I carry it to anyone at all. It's the only rule. You never, ever ask who."},
        {"noelle", "Well. I've had a long day, Pip. Give me that pencil. \"Dear anyone.\""},
        {"noelle", "\"Is everyone here this stubborn, or is it just the man who sells the trees?\""},
    }},
    {key="after-06", phase="after", level=6, lines={
        {"noelle", "Look in the ice! Hundreds of ribbons, red and gold, all frozen in the fountain."},
        {"agnes", "Wish ribbons. You tie one on in December, and the fountain keeps it till spring."},
        {"noelle", "An answer already! \"It's everyone. Him especially. Are you eating enough? Someone.\""},
        {"pip", "I'm not allowed to say who. I don't know who! I do know. I don't!"},
        {"wren", "The ice is thinner than it looks, this year."},
    }},
    {key="after-07", phase="after", level=7, lines={
        {"agnes", "There. She's lit. Forty years on a kitchen stove, and listen to that oven purr."},
        {"pip", "Message from Mr Strand! He says he doesn't want a bun."},
        {"agnes", "Tell him nobody offered."},
        {"pip", "He gave me a penny for one anyway. He says it's for me. He says to leave it on his step, for me."},
        {"noelle", "Agnes, what happened with you two?"},
        {"agnes", "Eat your gingerbread. It's better hot."},
    }},
    {key="after-08", phase="after", level=8, lines={
        {"noelle", "People keep stopping to look. And Bramble's got into all the tinsel. Whose goat is that?"},
        {"theo", "Finch's. She ate my invoice book last year. I've never been happier."},
        {"noelle", "Was that a joke? Did you just make a joke?"},
        {"theo", "Your arch is still in my way."},
    }},
    {key="after-09", phase="after", level=9, lines={
        {"noelle", "Mrs Alder, first cocoa's on me. In fact, I've got something for you. You're on your own, aren't you?"},
        {"pip", "Mrs Alder's got nineteen grandchildren! She says keep your parcel, and bring her a stool."},
        {"noelle", "Oh. Right. Then who does need it?"},
        {"wren", "Good cocoa. You'll know when you know. You've a little on your nose."},
        {"pip", "Another one came for you! \"Dear anyone. You sound like you could use a day off. So could I. Someone.\""},
    }},
    {key="before-10", phase="before", level=10, lines={
        {"noelle", "The big fir's still under the drift. Tonight, Pip. We'll put up the first string of lights."},
        {"pip", "Mum's steamer docks at Christmas, if the sea's kind. She might get home. I don't mind if she doesn't."},
        {"agnes", "Course you don't, pet. Have a bun. Have two."},
    }},
    {key="after-10", phase="after", level=10, lines={
        {"noelle", "Ready? Theo, you've got the plug. Don't say anything."},
        {"theo", "I was going to say it's upside down."},
        {"pip", "IT'S ON! Everyone's coming out! Look! All of them!", story.SHOUT},
        {"agnes", "Well. Would you look at that. I'd forgotten it could look like this."},
        {"noelle", "It's one string of lights."},
        {"wren", "It usually is."},
        {"pip", "Noelle! Mr Strand's come down to his door. He's looking this way. He hasn't been out after dark in years."},
        {"agnes", "Hmph. He's got his good scarf on."},
        {"pip", "And there's a note for you. It's only short."},
        {"noelle", "\"I heard you're leaving on the twenty-sixth. That's a pity. Stay for the cocoa, at least. Someone.\""},
        {"noelle", "Three weeks. It's only three weeks. So why did I just smile at a piece of paper?", story.THOUGHT},
    }},
    {key="before-11", phase="before", level=11, lines={
        {"pip", "Everyone wants a go! Mrs Alder's sent nine! Mr Finch has written one to his goat!"},
        {"noelle", "What have I started?"},
        {"wren", "Oh, you'd be surprised how far one goes. Is that a pencil you're not using?"},
        {"noelle", "\"Dear Someone. I'm not staying. But tell me something good about this place.\""},
        {"theo", "You're out late. Writing home?"},
        {"noelle", "None of your business. Haven't you got trees to be rude about?"},
        {"theo", "Night, then."},
    }},
    {key="after-11", phase="after", level=11, lines={
        {"noelle", "\"The carolers are terrible, and nobody's ever told them. That's the good thing. Someone.\""},
        {"noelle", "Pip, this note's all sticky at the corner. What is that, cough sweet?"},
        {"pip", "I can't hear you! I'm very busy! Bye!"},
        {"agnes", "They are dreadful. Fifty years. Give them some cocoa."},
    }},
    {key="after-12", phase="after", level=12, lines={
        {"pip", "Upper Fenwick says THEY'RE the best market in the north! Eleven thousand bulbs!"},
        {"agnes", "Raisins in their gingerbread, that's what they've got. It's a scandal."},
        {"theo", "They buy their trees from me, you know. They always pick the crooked ones."},
        {"noelle", "You've got a tree for every occasion. Stop staring at my parcel."},
        {"theo", "What's in it? You never put it down."},
        {"noelle", "No idea. It's for whoever needs it most."},
    }},
    {key="after-13", phase="after", level=13, lines={
        {"henrik", "Henrik Strand. That's the first proper window I've had in years."},
        {"henrik", "Who hung that arch? It's very nearly straight."},
        {"noelle", "You can see the whole square from there. And right into the bakery."},
        {"henrik", "Can you? Hadn't noticed. Tell that woman her window wants cleaning."},
        {"noelle", "Tell her yourself. It's thirty feet."},
        {"henrik", "It's further than it looks."},
    }},
    {key="after-14", phase="after", level=14, lines={
        {"noelle", "\"If you could have one day here, what would you do? Someone.\" Isn't that a nice question?"},
        {"noelle", "Theo, you're smiling at a piece of paper. Is it a bill?"},
        {"theo", "It's a... yes. A bill. A very reasonable bill. Is that a note you've got?"},
        {"noelle", "It's a list. A shopping list."},
        {"pip", "You never ask who. That's the rule. I'm going to explode. I am actually going to explode.", story.THOUGHT},
    }},
    {key="after-15", phase="after", level=15, lines={
        {"noelle", "Bramble! How did you get on the bakery roof? And what are you wearing?"},
        {"pip", "All of it. She's wearing all of the tinsel."},
        {"theo", "I'd leave her up there. Best decoration in Bellmere."},
    }},
    {key="after-16", phase="after", level=16, lines={
        {"noelle", "That's a good bow, Pip! Who's the present for?"},
        {"pip", "Nobody. It's a scarf. I knitted it. It's just practice. For nobody."},
        {"noelle", "Pip. Do you want this parcel of mine? I think it might be for you."},
        {"pip", "Nah. It's for whoever needs it most. I'm fine. If she doesn't come, I'll post the scarf."},
        {"noelle", "Oh, Pip. Come here."},
    }},
    {key="after-17", phase="after", level=17, lines={
        {"henrik", "Old carousel's been in my shed for years. Twelve horses, no paint. Thought someone might want it."},
        {"noelle", "It'd be the heart of the whole market! But we'll never paint twelve in time."},
        {"wren", "You'd be surprised how many people own a paintbrush."},
        {"pip", "I told Mrs Alder. She's told everyone. It's already a whole thing."},
    }},
    {key="after-18", phase="after", level=18, lines={
        {"pip", "Nine days to go, and the lights are up all down the lane! You can see us from the top road!"},
        {"noelle", "\"I walked the lane tonight. You were right about the carolers. I may have sung. Noelle.\""},
        {"noelle", "Oh no. I signed it. I signed it, Pip, give it back! ...Pip? Come back here!"},
    }},
    {key="after-19", phase="after", level=19, lines={
        {"noelle", "Let's shift that old post box before it goes through the floor. Careful, the lining's coming off."},
        {"pip", "There's something behind it! An old envelope. It's gone all brown. It's never been delivered!"},
        {"noelle", "\"H. Strand.\" In very firm handwriting. There's flour in the fold. Pip, that's forty years old."},
        {"pip", "I can take it! I can take it right now! A penny a message!"},
        {"noelle", "No. This one I'll carry myself."},
        {"wren", "Ah. There it is. I did wonder."},
    }},
    {key="before-20", phase="before", level=20, lines={
        {"noelle", "Mr Strand? It's late, I know. This is yours. It got stuck. For rather a long time."},
        {"henrik", "That's Agnes Holt's writing."},
        {"noelle", "I haven't read it. I think you should."},
    }},
    {key="after-20", phase="after", level=20, lines={
        {"henrik", "\"Meet me by the big fir on Christmas Eve. Don't be late. A.\" ...Forty years ago."},
        {"noelle", "She waited for you, didn't she?"},
        {"henrik", "She thought I didn't come. I thought she'd just stopped speaking to me. I've been cross for forty years."},
        {"noelle", "Mr Strand, where are you going? You've no coat on!"},
        {"pip", "He's crossing the square! Everyone! HE'S CROSSING THE SQUARE!", story.SHOUT},
        {"agnes", "What do you want? Tell that man I'm closed."},
        {"henrik", "Tell her yourself. No. Agnes. I never got your letter. It was behind the lining."},
        {"agnes", "You daft old... Forty years. You're late."},
        {"henrik", "I know. Is there a bun?"},
        {"agnes", "Course there's a bun. Get in here, you'll catch your death."},
        {"noelle", "Eleven days till I leave. And Pip's just handed me a note I'm scared to open.", story.THOUGHT},
    }},
    {key="before-21", phase="before", level=21, lines={
        {"pip", "They've been in there all night! There's laughing! It's horrible!"},
        {"noelle", "Pip, this came. I signed mine, and now look. \"Dear Noelle. Meet me by the big fir on Christmas Eve.\""},
        {"noelle", "\"I promise I'll get your letter. Someone.\""},
        {"pip", "So you'll go! Will you go? You have to go! I don't know why! I don't know anything!"},
        {"noelle", "My train's the twenty-sixth, Pip. It wouldn't be fair on anyone."},
        {"wren", "It's a good fir, that. Very reliable."},
        {"agnes", "Eight days, and that carousel's got no paint. Move, the lot of you. I've got a man to feed."},
    }},
    {key="after-21", phase="after", level=21, lines={
        {"pip", "The Finches painted their horse red, and the goat. Mrs Alder's lot used nineteen colours!"},
        {"noelle", "Where did the tuba come from?"},
        {"agnes", "Nobody knows. It just turns up in December."},
    }},
    {key="after-22", phase="after", level=22, lines={
        {"theo", "Half of Fenwick's here, holding your ladders. Someone told them about the cocoa."},
        {"noelle", "Why are you being nice?"},
        {"theo", "I've moved my trees. Round your arch. It looks better there. Don't tell anyone."},
    }},
    {key="after-23", phase="after", level=23, lines={
        {"noelle", "It's turning! Look, it's really turning! I'm not crying, it's the cold."},
        {"henrik", "The third horse is a touch to the left. I'll fix that."},
        {"agnes", "You'll leave it alone and have a ride, you old fusspot."},
        {"theo", "Twelve families, twelve horses. You did that, you know. In three weeks. With one arch."},
        {"noelle", "I'm leaving on the twenty-sixth, Theo."},
        {"theo", "I know. Somebody told me."},
    }},
    {key="after-24", phase="after", level=24, lines={
        {"noelle", "The fountain's thawing at the edges. All the ribbons are bobbing up."},
        {"wren", "That one's yours, I think. It came up first."},
        {"noelle", "I never tied one. It's got my name on, in a child's writing."},
        {"agnes", "You were six. You came here with Rosa, one Christmas. You told it you wanted to live in the bakery."},
    }},
    {key="after-25", phase="after", level=25, lines={
        {"pip", "The steamer's in! Mum's telegram says she's on the last train, Christmas Eve!"},
        {"theo", "There's a big one coming in off the sea. They might stop the line at Fenwick."},
        {"pip", "They won't. They can't. I don't mind. I've got a stamp for the scarf, anyway."},
        {"noelle", "Oh, Pip. We'll get this rink done, and leave every light on for her."},
    }},
    {key="after-26", phase="after", level=26, lines={
        {"pip", "LOOK AT ME! I'M GOING SO FAST!", story.SHOUT},
        {"noelle", "Who's that, out in the middle? Going very slowly, holding on to each other?"},
        {"theo", "Is that Agnes Holt? In skates?"},
        {"agnes", "Eyes front, you lot. I'm seventy next year. Mind your own business. Henrik, you're on my foot."},
        {"henrik", "I'm forty years late. I'm allowed one foot."},
        {"noelle", "Here it comes. Can you feel that wind?"},
    }},
    {key="after-27", phase="after", level=27, lines={
        {"noelle", "It's Christmas Eve, and the wind's had all our lights down. The fuses have gone. The whole market's dark."},
        {"pip", "They've stopped the train at the Fenwick cutting! The driver can't see the signals!"},
        {"noelle", "I'm so sorry, Pip. I don't know what to do. I've only got three weeks' worth of anything."},
        {"wren", "Is that so? Look behind you."},
        {"agnes", "I've got every lamp from the bakery, and I want them back."},
        {"henrik", "Twenty toy lanterns. They do work. I made them. Straight."},
        {"theo", "All of Fenwick, and Mrs Alder's nineteen, and more ladders than I can count. Where do you want us?"},
        {"noelle", "All of you came?"},
        {"agnes", "You daft girl. Whose market do you think it is? Now, where do we put the lamps?"},
        {"noelle", "Along the line. All the way to the cutting. Let's bring that train home!"},
    }},
    {key="after-28", phase="after", level=28, lines={
        {"pip", "I can hear it! It's coming! It's coming down the lamps!", story.SHOUT},
        {"noelle", "Run, Pip. Go on. Run!"},
        {"pip", "MUM! MUM! I KNITTED YOU A SCARF! IT'S TERRIBLE! I DIDN'T MIND! I MINDED A LOT!", story.SHOUT},
        {"noelle", "Oh, look at him go."},
        {"theo", "You've got something in your eye, too."},
        {"noelle", "It's the cold."},
    }},
    {key="after-29", phase="after", level=29, lines={
        {"wren", "Nearly midnight. It's a fine tree. You've still got your parcel, I see."},
        {"noelle", "I've tried Mrs Alder. I've tried Pip. Here, you have it. Nobody's paid you for all that sweeping."},
        {"wren", "That's kind. Read the tag again, though. Slowly."},
        {"noelle", "\"For whoever needs it most.\" ...Oh. Oh, Gran. It's a key. And a note."},
        {"noelle", "\"It's the house on the square. Stay or don't, my darling. But you'll want a door.\""},
        {"wren", "Mind the third step. It's a sly one."},
    }},
    {key="before-30", phase="before", level=30, lines={
        {"agnes", "Well? It's five to midnight, and there's a man under that fir pretending to look at a tree."},
        {"noelle", "Which man?"},
        {"agnes", "Go and find out, love. Some of us waited forty years."},
    }},
    {key="after-30", phase="after", level=30, lines={
        {"noelle", "You. Of course it's you. You've got resin on your note. You've had resin on every note!"},
        {"theo", "Your arch is in my way."},
        {"noelle", "You never asked who. That's the rule."},
        {"theo", "I knew by the second one. Nobody else is that rude about trees. I'm here anyway."},
        {"pip", "I KNEW THE WHOLE TIME! I KNEW FOR WEEKS! IT WAS AWFUL!", story.SHOUT},
        {"agnes", "Then light the thing, somebody! Henrik, your ladder's on the wrong side!"},
        {"noelle", "Here goes. Everyone, all together!"},
        {"pip", "IT'S ON! LOOK AT IT! LOOK AT THE WHOLE TOWN!", story.SHOUT},
        {"noelle", "We built this little market together. Merry Christmas!"},
        {"theo", "And the twenty-sixth?"},
        {"noelle", "Bramble's eaten my ticket. I'm told there's a house. It has a very sly step."},
        {"pip", "Hey, where's Mr Wren? His broom's here. There's a note on it."},
        {"noelle", "\"Well swept, all of you. Fernhollow, up the line, has never had a market. They've heard about the cocoa.\""},
        {"agnes", "I am not leaving my oven."},
        {"henrik", "It's coming with us. Get your good hat."},
    }},
}
